ay:"Vào cuộc đua",startCup:"Bắt đầu cúp 61 ghe",startQuick:"Bắt đầu đua với AI",continue:"Tiếp tục giải",newDraw:"Bốc thăm giải mới",preparing:"Đang chuẩn bị…",search:"Tìm ghe",searchHint:"Tên tiếng Việt hoặc Khmer",team:"Chọn đội ghe",teams:"Đội ghe",difficulty:"Độ khó",easy:"Dễ",normal:"Thi đấu",hard:"Thử thách",reference:"Màu và hoa văn có tư liệu tham khảo.",sample:"Phối màu lễ hội trong game; chưa xác minh bộ màu thật.",unknownKm:"Tên Khmer chưa xác minh",saved:"Nhánh đấu được lưu trên trình duyệt này.",cupFormat:"Cúp game có đủ 61 ghe, đua từng cặp và loại trực tiếp. Ba ghe được miễn vòng đầu. Kết quả do bạn chơi, không theo thứ hạng thật.",audio:"Âm thanh",audioSettings:"Tùy chỉnh âm thanh",atmosphere:"Không khí cuộc đua",voice:"BLV Việt (âm gốc)",khmer:"Bình luận Khmer (AI)",whistle:"Còi HLV theo nhịp dầm",drums:"Trống nhịp chèo",crowd:"Khán giả hai bờ",volume:"Âm lượng",mute:"Tắt âm thanh",unmute:"Bật âm thanh",audioError:"Chưa tải được một số âm thanh. Hãy bật lại tiếng để thử lại.",audioIdle:"BLV Việt gốc · Khmer AI · Còi theo nhịp dầm",muted:"Đã tắt âm thanh",hearName:"Nghe tên Việt · Khmer",stopName:"Dừng nghe tên",hearHistory:"Nghe lịch sử thi đấu",stopHistory:"Dừng nghe lịch sử",profile:"Bình luận về đội ghe",profileNote:"Bản thu giọng BLV gốc. Tên chùa có thể dùng chung cho các đội cùng chùa.",stopped:"Đã dừng nghe.",loadingAudio:"Đang tải bản thu…",name:"Tên ghe",history:"Lịch sử thi đấu",voiceLabel:"giọng",missingOther:"Chưa xác định được bản thu bằng ngôn ngữ còn lại.",missingHistory:"Chưa tìm được đoạn BLV kể thành tích cũ của đội này.",missingName:"Chưa xác định được bản thu tên đội này trong clip.",enableVoice:"Bật kênh BLV Việt hoặc Khmer trong Âm thanh để nghe.",audioRetry:"Chưa phát được bản thu. Hãy thử lại.",source:"Nguồn",bracket:"Nhánh đấu",bracketTitle:"Nhánh đấu · 61 ghe",closeBracket:"Đóng nhánh đấu",simulated:"Các trận khác được mô phỏng theo bốc thăm; không dùng thứ hạng lịch sử để quyết định thắng thua.",bye:"Miễn vòng đầu",tieRepl